corrected_code:
const express = require('express');
const { MongoClient, ObjectId } = require('mongodb');
const { authenticateUser } = require('../middleware/auth');

const router = express.Router();
const client = new MongoClient(process.env.MONGODB_URI);

router.get('/api/scheduler/jobs/:jobId/logs', authenticateUser, async (req, res) => {
  const db = client.db('agenda_db');
  const job = await db.collection('agendaJobs').findOne({
    _id: new ObjectId(req.params.jobId),
    'data.userId': req.user.id,
  });
  if (!job) {
    return res.status(403).json({ error: 'Access denied: job not found or unauthorized' });
  }

  res.json({
    jobId: job._id,
    name: job.name,
    payload: job.data,
    lastRunAt: job.lastRunAt,
    failReason: job.failReason,
  });
});
